export const NEWS_RE = /reksa ?dana|obligasi|\bSBN\b|\bSUN\b|sukuk|IHSG|saham|suku bunga|BI[- ]?Rate|\bBI\b|rupiah|inflasi|The Fed|investor|pasar modal|OJK|yield/i;
async function cached(key, ttl, make) {
  const c = caches.default, ck = new Request("https://cache.local/" + key), hit = await c.match(ck);
  if (hit) return hit;
  const v = await make(), res = Response.json(v, { headers: { "cache-control": `public, max-age=${ttl}` } });
  // hasil kosong (sumber gagal) tidak disimpan supaya permintaan berikutnya mencoba lagi
  if (v && (Array.isArray(v) ? v.length : v.ok !== false && Object.keys(v).length)) await c.put(ck, res.clone());
  return res;
}
export const FUND_TYPES = ["Pasar Uang", "Pendapatan Tetap", "Campuran", "Saham", "Indeks"];
// Validasi isi upload: [[pid, nama, jenis, risiko, minimal]]. Hasil {rows} atau {error}.
export function checkFundList(list, known) {
  if (!Array.isArray(list) || !list.length || list.length > 400) return { error: "Daftar kosong atau terlalu panjang (maks. 400)." };
  const rows = [], seen = new Set();
  for (const x of list) {
    const [pid, name, type, risk, min] = Array.isArray(x) ? x : [], p = String(pid || "");
    if (!/^\d{1,8}$/.test(p) || (known && !known.has(p))) return { error: `ID produk tidak dikenal: ${p || "(kosong)"} — ${name || ""}` };
    if (seen.has(p)) return { error: `Produk dobel: ${name}` };
    if (!FUND_TYPES.includes(type)) return { error: `Jenis tidak dikenal untuk ${name}: ${type}` };
    const nm = String(name || "").trim().slice(0, 120), rk = String(risk || "").trim().slice(0, 30), mn = Math.round(+min);
    if (!nm || !rk || !(mn >= 0 && mn <= 1e10)) return { error: `Nama, risiko, atau minimal pembelian belum diisi: ${nm || p}` };
    seen.add(p); rows.push([p, nm, type, rk, mn]);
  }
  return { rows };
}
const URL_LIST = "https://www.bareksa.com/id/data/reksadana/daftar/?view=performance&trans=1&aum_value=0";

export function parseList(html) {
  const i = html.indexOf("var data = '");
  if (i < 0) throw new Error("Bareksa: 'var data' tidak ditemukan (len=" + html.length + ")");
  const start = i + 12;
  const raw = html.slice(start, html.indexOf("]';", start) + 1);
  return JSON.parse(raw.includes("\\'") ? raw.replace(/\\'/g, "'") : raw);
}

// nav.date Bareksa -> YYYY-MM-DD; kalau formatnya tak dikenal pakai tanggal yang diminta.
export function isoDate(s, fallback) {
  let m;
  if ((m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s || ""))) return m[0];
  if ((m = /^(\d{2})-(\d{2})-(\d{4})/.exec(s || ""))) return `${m[3]}-${m[2]}-${m[1]}`;
  const d = new Date(s);
  return isNaN(d) ? fallback : d.toISOString().slice(0, 10);
}

// Harian (hari kerja) sampai 5 tahun ke belakang, lalu tiap Jumat sampai 10 tahun (cukup untuk simulasi 10 tahun). Terbaru dulu.
export function backfillDates(today = new Date()) {
  const out = [];
  for (let n = 1; n <= 365 * 10 + 3; n++) {
    const d = new Date(today.getTime() - n * 864e5), wd = d.getUTCDay();
    if (n <= 365 * 5 ? wd >= 1 && wd <= 5 : wd === 5) out.push(d.toISOString().slice(0, 10));
  }
  return out;
}

const num = (v) => (v == null || v === "" || isNaN(+v) ? null : +v);

// "2026-08-01" -> "2026-07" (bulan AUM sebelumnya)
export function prevMonth(p) {
  const m = /^(\d{4})-(\d{2})/.exec(p || "");
  return m ? new Date(Date.UTC(+m[1], +m[2] - 2, 1)).toISOString().slice(0, 7) : null;
}
const isoOf = (d) => d.toISOString().slice(0, 10);

// Tanggal snapshot SELURUH PASAR untuk rating bintang: tiap Jumat 53 minggu terakhir (volatilitas 6 bln & 1 th)
// dan hari kerja terakhir tiap bulan, 37 bulan terakhir (volatilitas 3 th & unit growth). Terbaru dulu.
export function mktDates(today = new Date()) {
  const t = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())), out = new Set();
  for (let n = 1, k = 0; k < 53; n++) { const d = new Date(t - n * 864e5); if (d.getUTCDay() === 5) { out.add(isoOf(d)); k++; } }
  for (let m = 1; m <= 37; m++) {
    const d = new Date(Date.UTC(t.getUTCFullYear(), t.getUTCMonth() - m + 1, 0)); // hari terakhir bulan itu
    while (d.getUTCDay() === 0 || d.getUTCDay() === 6) d.setUTCDate(d.getUTCDate() - 1);
    out.add(isoOf(d));
  }
  return [...out].sort().reverse();
}
