      ret: { m1: num(d.return?.onemonth), m3: num(d.return?.threemonth), m6: num(d.return?.sixmonth),
             ytd: num(d.return?.ytd), y1: num(d.return?.oneyear), y3: num(d.return?.threeyear), y5: num(d.return?.fiveyear) },
