          const b = await req.json().catch(() => ({})), rfShort = +b.rfShort, rfLong = +b.rfLong, depo = b.depo == null ? 4 : +b.depo, okRf = (v) => v >= 0 && v <= 20;
          const biRate = b.biRate == null || b.biRate === "" ? null : +b.biRate;
          if (!okRf(rfShort) || !okRf(rfLong) || !okRf(depo) || (biRate != null && !okRf(biRate))) return Response.json({ error: "bunga harus 0–20" }, { status: 400 });
          const old = await env.DB.prepare("SELECT v FROM meta WHERE k='cfg'").first(), oc = old ? JSON.parse(old.v) : {};
          // tanggal ubah disimpan supaya Home bisa menulis "per tanggal"
          const at = { ...(oc.at || {}) }; for (const [k, v] of Object.entries({ rfShort, rfLong, depo, biRate })) if (oc[k] !== v) at[k] = new Date().toISOString().slice(0, 10);
          await env.DB.prepare("INSERT OR REPLACE INTO meta VALUES ('cfg', ?)").bind(JSON.stringify({ rfShort, rfLong, depo, biRate, at })).run();
